/// Whether the `String(value)` / `new String(value)` coercion may have side effects.
///
/// `String` applies `ToString` to its argument, which for objects calls
/// `Symbol.toPrimitive` / `toString` / `valueOf` and can execute user code.
/// The call is side-effect-free when there is no argument or the argument is a
/// known primitive (including a plain object literal that coerces to
/// `"[object Object]"`).
fn string_constructor_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    // String(value) calls ToPrimitive on object-like/unknown values.
    args.first().is_some_and(|arg| {
        arg.as_expression().is_none_or(|expr| expr.to_primitive(ctx).is_string().is_none())
    })
}

/// Whether the `Number(value)` / `new Number(value)` coercion may have side effects.
///
/// `Number` applies `ToNumber` to its argument, which throws on `Symbol` and can
/// execute user code (`Symbol.toPrimitive` / `valueOf` / `toString`) during
/// `ToPrimitive`. It is side-effect-free for known primitives and plain object
/// literals.
fn number_constructor_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    // Number(value) throws on Symbol and can execute user code during ToPrimitive.
    args.first().is_some_and(|arg| {
        arg.as_expression().is_none_or(|expr| expr.to_primitive(ctx).is_symbol() != Some(false))
    })
}

/// Whether a `new Date(...)` call may have side effects.
///
/// `Date` is side-effect-free with no arguments, or with numeric / string literal
/// arguments. Any other argument (e.g. an unknown variable reference that could be
/// an object triggering `ToPrimitive`) is treated as side-effectful.
fn date_constructor_may_have_side_effects(args: &[Argument<'_>]) -> bool {
    args.iter().any(|arg| {
        !matches!(
            arg.as_expression(),
            Some(Expression::NumericLiteral(_) | Expression::StringLiteral(_))
        )
    })
}

/// Whether a `new ArrayBuffer(...)` call may have side effects.
///
/// `ArrayBuffer` is side-effect-free with no arguments or a numeric literal length.
/// An unknown variable reference could be an object whose `ToIndex` coercion runs
/// user code, so it is treated as side-effectful.
fn array_buffer_constructor_may_have_side_effects(args: &[Argument<'_>]) -> bool {
    args.iter().any(|arg| !matches!(arg.as_expression(), Some(Expression::NumericLiteral(_))))
}

/// Whether a typed array constructor call (e.g. `new Int8Array(...)`) may have side effects.
///
/// Side-effect-free with no arguments, a numeric literal length, or a plain object
/// literal (treated as an array-like). An object literal defining a custom iterator
/// (`[Symbol.iterator]`) can execute user code, and an unknown variable reference
/// could be an iterable/array-like triggering user code, so both are side-effectful.
fn typed_array_constructor_may_have_side_effects<'a>(
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    if args.iter().any(|e| e.may_have_side_effects(ctx)) {
        return true;
    }
    match args.first() {
        None => false,
        Some(arg) => match arg.as_expression() {
            Some(Expression::NumericLiteral(_)) => false,
            Some(Expression::ObjectExpression(obj)) => object_defines_custom_iterator(obj),
            _ => true,
        },
    }
}

/// Whether an object literal defines a custom iterator (`[Symbol.iterator]`).
fn object_defines_custom_iterator(obj: &ObjectExpression<'_>) -> bool {
    obj.properties.iter().any(|prop| match prop {
        ObjectPropertyKind::ObjectProperty(prop) => is_symbol_iterator_key(&prop.key),
        // A spread could bring in a `Symbol.iterator`, so be conservative.
        ObjectPropertyKind::SpreadProperty(_) => true,
    })
}

/// Whether a property key is the computed `[Symbol.iterator]` key.
fn is_symbol_iterator_key(key: &PropertyKey<'_>) -> bool {
    matches!(key, PropertyKey::StaticMemberExpression(member)
        if member.property.name == "iterator"
            && matches!(&member.object, Expression::Identifier(id) if id.name == "Symbol"))
}

